INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-ren','曹仁','wei','[]',NULL,NULL,168,1,NULL,'year',223,4,NULL,'month','["将领"]','曹魏宗室将领，字子孝，沛国谯人，曹操从弟。参与平定北方及赤壁后南征，曾镇守江陵、樊城；襄樊之战中抵御关羽围攻，后官至大司马。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹仁"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-xiu','曹休','wei','[]',NULL,NULL,NULL,NULL,NULL,NULL,228,6,NULL,'month','["将领"]','曹魏宗室将领，字文烈，沛国谯人，曹操族子。随军征讨孙权、蜀汉，历任征东将军等职；石亭之战被吴将陆逊击败，后因病去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹休"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-yu','关羽','shu','[]',NULL,NULL,160,1,NULL,'year',220,1,NULL,'year','["将领"]','蜀汉名将，襄樊之战北伐曹魏，兵败被俘遇害；关羽被杀后孙权送其首级给曹操；蜀汉追谥壮缪侯，民间崇奉逐渐神化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/关羽"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-zhong','黄忠','shu','[]',NULL,NULL,NULL,NULL,NULL,NULL,220,1,NULL,'year','["将领"]','蜀汉名将，定军山斩夏侯渊，助刘备夺取汉中；刘备称汉中王后封其为后将军，蜀汉追谥刚侯；正史未载确切生年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄忠"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-xun','陆逊','wu','[]',NULL,NULL,183,1,NULL,'year',245,8,NULL,'month','["军事家","政治家"]','孙吴名将，夷陵之战、石亭之战主将，后官至丞相；夷陵获胜后任荆州牧，晚年卷入孙和与孙霸储位争议，遭孙权责问而病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陆逊"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-su','马谡','shu','[]',NULL,NULL,NULL,NULL,NULL,NULL,228,1,NULL,'year','["将领"]','蜀汉将领，街亭之战违诸葛亮节度，兵败被斩；正史只记街亭失守后马谡被收监处死；“挥泪斩马谡”细节出自《三国演义》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马谡"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiahou-yuan','夏侯渊','wei','[]',NULL,NULL,NULL,NULL,NULL,NULL,219,1,NULL,'year','["将领"]','东汉末至三国曹魏将领，字妙才，沛国谯人，曹操族弟。长期镇守关中、凉州及汉中，定军山之战中遭刘备军突袭阵亡；以善于长途奔袭著称。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夏侯渊"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-fei','张飞','shu','[]',NULL,NULL,168,1,NULL,'year',221,6,NULL,'month','["将领"]','蜀汉名将，长坂之战掩护刘备撤退，后镇守阆中；被部将范强、张达刺杀后，二人携首级投奔孙权；蜀汉追谥桓侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张飞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-he','张郃','wei','[]',NULL,NULL,NULL,NULL,NULL,NULL,231,8,NULL,'month','["将领"]','曹魏名将，字儁乂，河间鄚人。原为袁绍部将，官渡之战后归曹操，参与平定北方及多次对蜀作战；街亭之战击败马谡，后在木门道与蜀军交战中中箭身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张郃"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-liao','张辽','wei','[]',NULL,NULL,169,1,NULL,'year',222,9,NULL,'month','["将领"]','东汉末至曹魏名将，字文远，雁门马邑人。先后效力丁原、董卓、吕布，归曹操后镇守合肥；逍遥津之战率精骑突击孙权军，成为魏吴战争中的著名战例。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张辽"}]',NULL,NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('changban','长坂之战','battle','point','year',NULL,NULL,'建安十三年，208年，刘备南逃于长坂遭曹军追击',208,12,NULL,2507,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'曹操南下荆州，刘备携百姓南奔，于长坂遭曹军追上；张飞断后，赵云救主，奠定孙刘联盟基础。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('dingjunshan','定军山之战','battle','point','month',NULL,NULL,'建安二十四年正月，黄忠斩夏侯渊',219,1,NULL,2628,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'黄忠于定军山斩曹魏大将夏侯渊，汉中战局逆转，刘备军占上风。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('hanzhong','汉中之战','battle','span',NULL,'month','month','建安二十二年至二十四年五月',NULL,NULL,NULL,NULL,217,1,NULL,2604,219,5,NULL,2632,'刘备与曹操争夺汉中，历时近两年，刘备最终占据汉中并称汉中王。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('jieting','街亭之战','battle','point','year',NULL,NULL,'建兴六年春，228年',228,12,NULL,2747,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'诸葛亮第一次北伐，马谡守街亭违令，兵败于张郃，蜀军被迫撤退。',NULL,NULL,'[]');
