INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('shiting','石亭之战','battle','point','month',NULL,NULL,'黄初七年七月，228年',228,7,NULL,2742,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'陆逊于石亭大败曹休，斩获甚众，孙吴北方边境得以巩固。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('wuzhangyuan','五丈原之战','battle','span',NULL,'month','month','建兴十二年二月至八月',NULL,NULL,NULL,NULL,234,2,NULL,2809,234,8,NULL,2815,'诸葛亮最后一次北伐，屯兵五丈原与魏军对峙，八月病逝军中，蜀军退归。',NULL,NULL,'[]');
